#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include "lcms2.h"

int main(int argc, char** argv) {
    if (argc < 2) return 0;
    FILE* f = fopen(argv[1], "rb");
    if (!f) return 0;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char* buf = malloc(sz);
    fread(buf, 1, sz, f);
    fclose(f);
    cmsHANDLE handle = cmsIT8LoadFromMem(0, buf, sz);
    if (handle) cmsIT8Free(handle);
    free(buf);
    return 0;
}
